var UTM_KEYS=['utm_source','utm_medium','utm_campaign','utm_term','utm_content'];
function utmBuild(base, params){
  if(typeof base!=='string') return {error:'base must be string'};
  params=params||{};
  var qIndex=base.indexOf('?');
  var path=base, existing='';
  if(qIndex>=0){ path=base.slice(0,qIndex); existing=base.slice(qIndex+1); }
  var pairs=[];
  if(existing) existing.split('&').forEach(function(p){ if(p) pairs.push(p); });
  UTM_KEYS.forEach(function(k){
    var v=params[k];
    if(v!==undefined && v!==null && String(v).length>0){
      pairs.push(k+'='+encodeURIComponent(String(v)));
    }
  });
  return {value: path + (pairs.length?('?'+pairs.join('&')):''), error:null};
}
function utmParse(url){
  if(typeof url!=='string') return {error:'url must be string'};
  var qIndex=url.indexOf('?');
  var base=url, query='';
  if(qIndex>=0){ base=url.slice(0,qIndex); query=url.slice(qIndex+1); }
  var all={}, utm={};
  query.split('&').forEach(function(p){
    if(!p) return;
    var eq=p.indexOf('=');
    var k=eq>=0?p.slice(0,eq):p;
    var v=eq>=0?p.slice(eq+1):'';
    k=decodeURIComponent(k); v=decodeURIComponent(v);
    all[k]=v;
    if(k.indexOf('utm_')===0) utm[k]=v;
  });
  return {base:base, utm:utm, all:all, error:null};
}
function utmValidate(params){
  params=params||{};
  var issues=[];
  if(!params.utm_source || !String(params.utm_source).trim()) issues.push('utm_source 缺失或为空');
  ['utm_medium','utm_campaign','utm_term','utm_content'].forEach(function(k){
    if(params[k]!==undefined && params[k]!==null && String(params[k]).length===0) issues.push(k+' 为空');
  });
  return {valid: issues.length===0, issues:issues, normalized:params};
}
if (typeof module !== 'undefined' && module.exports) {
  module.exports = { build:utmBuild, parse:utmParse, validate:utmValidate };
}
if (typeof window !== 'undefined') {
  window.UtmForgePure = { build:utmBuild, parse:utmParse, validate:utmValidate };
}
